<?php require '../config/database.php';auth();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)die('العميل غير موجود');if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('UPDATE customers SET name=?,phone=?,email=?,address=?,notes=? WHERE id=?');$s->execute([$_POST['name'],$_POST['phone'],$_POST['email'],$_POST['address'],$_POST['notes'],$id]);header('Location:index.php');exit;}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>تعديل عميل</h1><form method="post"><label>الاسم</label><input name="name" value="<?=htmlspecialchars($r['name'])?>" required><label>الهاتف</label><input name="phone" value="<?=htmlspecialchars($r['phone'])?>"><label>البريد</label><input name="email" value="<?=htmlspecialchars($r['email'])?>"><label>العنوان</label><input name="address" value="<?=htmlspecialchars($r['address'])?>"><label>ملاحظات</label><textarea name="notes"><?=htmlspecialchars($r['notes'])?></textarea><button>حفظ</button></form></main>
